import pefile,struct
pe=pefile.PE('Fast.exe');d=open('Fast.exe','rb').read();IB=0x400000
# thunk region: find all 'sub [esp+4],imm32; jmp rel32' and 'jmp rel32' thunks
def isthunkptr(v):
    try: f=pe.get_offset_from_rva(v-IB)
    except: return False
    return d[f]==0xe9 and v<0x55b970 and v>0x430000
runs=[];cur=[]
for f in range(0x1000,0x297000,4):
    v=struct.unpack_from('<I',d,f)[0]
    if isthunkptr(v): cur.append(v)
    else:
        if len(cur)>=3: runs.append((IB+pe.get_rva_from_offset(f-4*len(cur)),len(cur),cur))
        cur=[]
for va,n,c in runs: print(hex(va),n,hex(c[0]),hex(c[-1]))
EOF
