import json,pickle,bisect
pm=json.load(open('procmap.json'))
starts=[]
for obj,l in pm.items():
    for i,nm,t in l: starts.append((int(t,16),'%s.%s[%d]'%(obj,nm,i)))
starts.sort(); addrs=[s[0] for s in starts]
def where(a):
    k=bisect.bisect_right(addrs,a)-1
    return starts[k][1]+'@%x'%starts[k][0] if k>=0 else '?'
uses=pickle.load(open('fconst.pkl','rb'))
