byproc=collections.defaultdict(list)
for (a,k,v),u in uses.items():
    if v==0.0: continue
    for x in u:
        if 0x55b970<=x<0x695830: byproc[where(x)].append(round(v,6))
for p in sorted(byproc, key=lambda s:int(s.split('@')[1],16)):
    print(p, sorted(set(byproc[p])))
