cd /tmp/ericfast/opus && cat > fulldis.py <<'EOF'
import pefile,struct,re,json,bisect
from capstone import *
pe=pefile.PE('Fast.exe');d=open('Fast.exe','rb').read();IB=0x400000
off=lambda v: pe.get_offset_from_rva(v-IB)
iat={}
for e in pe.DIRECTORY_ENTRY_IMPORT:
    for i in e.imports: iat[i.address]=(i.name or b'ord%d'%i.ordinal).decode()
# thunks "jmp [iat]" in the low text
md=Cs(CS_ARCH_X86,CS_MODE_32); md.skipdata=True
names={}
pm=json.load(open('procmap.json'))
for obj,l in pm.items():
    for i,nm,t in l: names[int(t,16)]='%s.%s[%d]'%(obj,nm,i)
# find import jmp stubs anywhere in first 0x2000 of text
for f in range(0x1000,0x1000+0x9000):
    if d[f]==0xff and d[f+1]==0x25:
        a=struct.unpack_from('<I',d,f+2)[0]
        if a in iat: names.setdefault(IB+pe.get_rva_from_offset(f),'stub_'+iat[a])
def fval(addr,dbl):
    try:
        g=off(addr)
        return struct.unpack_from('<d' if dbl else '<f',d,g)[0]
    except: return None
out=open('fulldis.txt','w')
s,e=0x55b970,0x695830
g=off(s)
for ins in md.disasm(d[g:g+(e-s)],s):
    a=ins.address
    if a in names: out.write('\n;===== %s\n'%names[a])
    ann=''
    m=re.search(r'0x([0-9a-f]+)',ins.op_str)
    if m:
        v=int(m.group(1),16)
        if v in iat: ann=iat[v]
        elif v in names: ann=names[v]
        if ins.mnemonic.startswith('f') and 'ptr [0x' in ins.op_str:
            ann='= %r'%fval(v,'qword' in ins.op_str)
    out.write('%x: %-8s %-40s %s\n'%(a,ins.mnemonic,ins.op_str,(';'+ann) if ann else ''))
out.close()
json.dump({hex(k):v for k,v in names.items()},open('names_all.json','w'))
EOF
venv/bin/python -I fulldis.py && wc -l fulldis.txt && grep -c stub_ names_all.json; grep -E '_CIcos|_CIexp|_CIsin|_CIlog|PowerR8' fulldis.txt | head; grep -o 'stub_[A-Za-z_]*' names_all.json | head -3

