import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

public class DecompList extends GhidraScript {
    public void run() throws Exception {
        String[] a = getScriptArgs();
        String out = a[0];
        // optional names file: lines "hexaddr name"
        List<String> lines = Files.readAllLines(Paths.get(a[1]));
        Map<Long,String> names = new LinkedHashMap<>();
        for (String l : lines) { l=l.trim(); if (l.isEmpty()) continue; String[] p=l.split("\\s+",2); names.put(Long.parseLong(p[0].replace("0x",""),16), p.length>1?p[1]:null); }
        Set<Long> want = new LinkedHashSet<>();
        for (int i=2;i<a.length;i++) want.add(Long.parseLong(a[i].replace("0x",""),16));
        // create functions at all named addresses
        for (Map.Entry<Long,String> e : names.entrySet()) {
            Address ad = toAddr(e.getKey());
            Function f = getFunctionAt(ad);
            if (f == null) { disassemble(ad); f = createFunction(ad, null); }
            if (f != null && e.getValue()!=null) {
                try { f.setName(e.getValue().replaceAll("[^A-Za-z0-9_]","_"), SourceType.USER_DEFINED);} catch(Exception ex){}
            }
        }
        DecompInterface di = new DecompInterface();
        di.openProgram(currentProgram);
        PrintWriter pw = new PrintWriter(new FileWriter(out));
        for (Long w : want) {
            Function f = getFunctionContaining(toAddr(w));
            if (f == null) { pw.println("// no function at "+Long.toHexString(w)); continue; }
            DecompileResults r = di.decompileFunction(f, 600, monitor);
            pw.println("// ===== "+f.getName()+" @ "+f.getEntryPoint()+" body "+f.getBody().getMinAddress()+"-"+f.getBody().getMaxAddress());
            if (r.decompileCompleted()) pw.println(r.getDecompiledFunction().getC()); else pw.println("// FAILED: "+r.getErrorMessage());
            pw.flush();
        }
        pw.close();
    }
}
EOF
