import re,json,bisect
names={int(k,16):v for k,v in json.load(open('names_all.json')).items() if not v.startswith('stub')}
for p in json.load(open('prologues.json')): names.setdefault(int(p,16),'proc_'+p[2:])
st=sorted(names)
def where(a):
    k=bisect.bisect_right(st,a)-1; return '%s@%x'%(names[st[k]],st[k])
import collections
c=collections.defaultdict(set)
for l in open('fulldis.txt'):
    if l[:1] in ';\n': continue
    m=re.search(r'(fstp|mov) +(dword|word) ptr \[e[a-z]x \+ (0x2(3[4-9a-f]|[4-6][0-9a-f]))\]',l)
    if m:
        a=int(l.split(':')[0],16); c[where(a)].add(m.group(3))
for k,v in sorted(c.items(), key=lambda x:x[0].split('@')[1]): print(k, sorted(v))
"

